import{_ as i,a0 as e,w as r,s as l,ao as a,I as s,x as u,a1 as p,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux 有问必答：如何通过代理服务器安装 Ubuntu 桌面版 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何通过代理服务器安装 Ubuntu 桌面版 | LCTT (201603) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何通过代理服务器安装 Ubuntu 桌面版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何通过代理服务器安装 Ubuntu 桌面版 | LCTT (201603) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201603/20151105 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy","title":"Linux 有问必答：如何通过代理服务器安装 Ubuntu 桌面版","tag":"201603","desc":""},"relativePath":"201603/20151105 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md","filePath":"[post].md"}'),b={name:"201603/20151105 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md"};function d(m,t,c,x,g,_){const n=e("Link");return r(),l("div",null,[t[13]||(t[13]=a(`<h1 id="linux-有问必答-如何通过代理服务器安装-ubuntu-桌面版" tabindex="-1">Linux 有问必答：如何通过代理服务器安装 Ubuntu 桌面版 <a class="header-anchor" href="#linux-有问必答-如何通过代理服务器安装-ubuntu-桌面版" aria-label="Permalink to “Linux 有问必答：如何通过代理服务器安装 Ubuntu 桌面版”">​</a></h1><blockquote><p><strong>问题</strong>: 我的电脑通过 HTTP 代理连接到公司网络。当我尝试从 CD-ROM 在计算机上安装 Ubuntu 桌面时，在检索文件时安装程序会被挂起，检索则不会完成，这可能是由于代理造成的。然而问题是，Ubuntu 的安装程序从不要求我在安装过程中配置代理。那我该怎么使用代理来安装 Ubuntu 桌面？</p></blockquote><p>与 Ubuntu 服务器不太一样，安装 Ubuntu 桌面几乎都是自动安装，没有留下太多自定义的空间，如自定义磁盘分区，手动网络设置，包选择等等。尽管非常简单，一键安装被认为是用户友好的，它不需要用户寻找“高级安装模式”来定制自己的 Ubuntu 桌面。</p><p>此外，Ubuntu 默认桌面的安装程序中一个大问题是代理设置。如果你的计算机连接在一个代理上，你会发现 Ubuntu 安装时会卡在准备下载文件处。</p><p><img src="https://c2.staticflickr.com/6/5683/22195372232_cea81a5e45_c.jpg" alt=""></p><p>这篇文章描述了如何解决当使用代理时 Ubuntu <strong>安装程序的限制和安装 Ubuntu 桌面</strong>。</p><p>其基本思路如下。不是直接使用 Ubuntu 的安装程序开始安装，首先进入 live Ubuntu 桌面，配置代理服务器，最后从 live 桌面手动启动 Ubuntu 的安装程序。以下是程序的安装步骤。</p><p>从 CD/DVD 或 USB 启动 Ubuntu 桌面后，点击第一个欢迎屏幕上的&quot;Try Ubuntu&quot;。</p><p><img src="https://c1.staticflickr.com/1/586/22195371892_3816ba09c3_c.jpg" alt=""></p><p>一旦进入 live Ubuntu 桌面，点击左侧设置图标。</p><p><img src="https://c1.staticflickr.com/1/723/22020327738_058610c19d_c.jpg" alt=""></p><p>进入 Network 菜单。</p><p><img src="https://c2.staticflickr.com/6/5675/22021212239_ba3901c8bf_c.jpg" alt=""></p><p>手动配置代理服务器。</p><p><img src="https://c1.staticflickr.com/1/735/22020025040_59415e0b9a_c.jpg" alt=""></p><p>接下来，打开一个终端。</p><p><img src="https://c2.staticflickr.com/6/5642/21587084823_357b5c48cb_c.jpg" alt=""></p><p>通过输入以下命令切换到 root 用户：</p><pre><code>$ sudo su
</code></pre><p>最后，在 root 用户下输入以下命令。</p><pre><code># ubiquity gtk_ui
</code></pre><p>然后将启动基于 GUI 的 Ubuntu 安装程序。</p><p><img src="https://c1.staticflickr.com/1/723/22020025090_cc64848b6c_c.jpg" alt=""></p><p>继续安装其余部分。</p><p><img src="https://c1.staticflickr.com/1/628/21585344214_447020e9d6_c.jpg" alt=""></p><hr>`,26)),s("p",null,[t[1]||(t[1]=u("via: ",-1)),p(n,{href:"http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html"},{default:o(()=>[...t[0]||(t[0]=[u("http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=u("作者：",-1)),p(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[2]||(t[2]=[u("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=u(" 译者：",-1)),p(n,{href:"https://github.com/strugglingyouth"},{default:o(()=>[...t[3]||(t[3]=[u("strugglingyouth",-1)])]),_:1}),t[7]||(t[7]=u(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[u("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=u("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[u("LCTT",-1)])]),_:1}),t[11]||(t[11]=u(" 原创编译，",-1)),p(n,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[u("Linux中国",-1)])]),_:1}),t[12]||(t[12]=u(" 荣誉推出",-1))])])}const T=i(b,[["render",d]]);export{k as __pageData,T as default};
